query.syntax:
if (true) {
  var a = 1;
  let b = 2;
}
// a is visible here, b is not

// General form: backtick-delimited string with embedded expressions
// `text ${expression} more text`
// Each ${...} is evaluated, converted to a string, and spliced in.

const lang = "JavaScript";
const msg = `I like ${lang}`;        // "I like JavaScript"

const a = 3, b = 4;
const sum = `Total: ${a + b}`;       // "Total: 7"

// Any expression works inside ${}: literals, calls, ternaries
`${"Grace".toUpperCase()}`;          // "GRACE"
`${a > b ? "big" : "small"}`;        // "small"

// Multi-line strings keep their line breaks
const lines = `line one
line two`;

// Gotchas:
// - Only backticks interpolate; '${x}' and "${x}" stay literal text
// - Values are converted with String(): `${null}` -> "null",
//   `${[1, 2]}` -> "1,2", `${{}}` -> "[object Object]"
// - Escape a literal ${ with a backslash: `\${x}` -> "${x}"
// - Tagged templates: tag`a ${x}` calls tag(strings, x) instead

// General form:
//   `text ${expression} more text`
// The expression inside ${...} is evaluated, converted to a string,
// and spliced into the surrounding text.

const who = "Sam";
const k = 3;
const s1 = `Hi ${who}, you have ${k + 1} items`;

// Any expression is allowed inside ${...}, including function calls,
// ternaries, and other template literals:
const tag = (x) => `<${x}>`;
const s2 = `${tag(who)} is ${k > 2 ? "big" : "small"}`;

// Gotchas:
// - ${...} is a full JavaScript expression context, so the parser
//   treats backticks inside it as the start of a new literal,
//   not as text.
// - Outside of ${...}, a backtick must be escaped as \` and a
//   literal "${" as \${ to be kept as plain text.
// - Values are converted with ToString: null -> "null",
//   undefined -> "undefined", objects -> their toString().
// - Newlines in the source are kept in the resulting string.
// - Tagged form: fn`text ${v}` calls fn with the string parts
//   and the values instead of building a string directly.

// General form: a tag function placed before a template literal
// String.raw`text ${expr} more` -> string with escapes left uncooked

const path = String.raw`C:\temp\docs`;
// path === 'C:\\temp\\docs' (backslashes kept literally, length 12)

const tabbed = String.raw`a\tb`;
// 'a\\tb' -> 4 chars: a, \, t, b (no tab character)

const who = 'Ana';
String.raw`Hi\x21 ${who}`; // 'Hi\\x21 Ana' - substitutions still run

// Called as a plain function:
String.raw({ raw: ['x', 'y', 'z'] }, 1, 2); // 'x1y2z'

