// General form
// arr.find(callback(element, index, array), thisArg?)
// Returns the FIRST element for which callback returns truthy,
// or undefined if no element matches.

const users = [
  { name: "Ada", age: 36 },
  { name: "Linus", age: 28 },
  { name: "Grace", age: 45 },
];

users.find((u) => u.age > 30);   // { name: "Ada", age: 36 }
users.find((u) => u.age > 100);  // undefined

['x', 'y', 'z'].find((s, i) => i === 2); // 'z'

