// arr.findIndex(fn)     -> index of first match, or -1
// arr.findLast(fn)      -> last matching element, or undefined (ES2023)
// arr.findLastIndex(fn) -> index of last match, or -1 (ES2023)
// arr.filter(fn)        -> array of ALL matches, or []
// arr.some(fn)          -> true/false

// Gotchas:
// - Not null: a miss gives undefined.
// - If an element itself is undefined and matches, you can't tell
//   it apart from "no match"; use findIndex instead.
// - Stops at the first match (short-circuits).
// - Visits holes in sparse arrays as undefined.
// - Returns the element itself (same object reference), not a copy.

// General form
// arr.findIndex(callbackFn(element, index, array), thisArg?)
// Returns the index of the FIRST element for which callbackFn is truthy.
// Returns -1 if no element matches.

const temps = [12, 18, 25, 31];
temps.findIndex((t) => t > 20);   // 2
temps.findIndex((t) => t > 100);  // -1  (no match)

const users = [{ name: "Ana" }, { name: "Bo" }];
const i = users.findIndex((u) => u.name === "Bo"); // 1
if (i !== -1) users[i].name = "Bob";

// Variations and gotchas:
// - find() returns the element itself (or undefined), not the index.
// - findLastIndex() searches from the end; also returns -1 on no match.
// - indexOf(value) uses strict equality instead of a callback; -1 on no match.
// - Check with `i !== -1` or `i >= 0`; `if (i)` wrongly fails for index 0.
// - Empty slots in sparse arrays are visited as undefined.
// - Stops at the first match; the callback is not run on later elements.

// General form
arr.includes(searchElement)
arr.includes(searchElement, fromIndex)
// Returns a boolean: true if found, false otherwise

// Examples
const fruits = ["apple", "pear", "plum"];
fruits.includes("pear");     // true
fruits.includes("grape");    // false
fruits.includes("apple", 1); // false (search starts at index 1)

// Variations and gotchas
// - Uses SameValueZero: NaN is found, unlike indexOf
[1, NaN].includes(NaN);   // true
[1, NaN].indexOf(NaN);    // -1
// - Strict comparison, no type coercion
[1, 2, 3].includes("2");  // false
// - Objects are compared by reference
[{ x: 1 }].includes({ x: 1 }); // false
// - Negative fromIndex counts from the end
[10, 20, 30].includes(10, -2); // false
// - Strings have their own includes for substrings
"hello".includes("ell");  // true
// - Use indexOf when you need the position, not a boolean

// General form
arr.indexOf(searchElement)
arr.indexOf(searchElement, fromIndex)
// Returns the first index where element === searchElement,
// or -1 if no match is found.

const fruits = ["apple", "pear", "plum", "pear"];
fruits.indexOf("pear");     // 1
fruits.indexOf("pear", 2);  // 3  (search starts at index 2)
fruits.indexOf("kiwi");     // -1 (not found)

// Common check for presence:
if (fruits.indexOf("plum") !== -1) { /* found */ }
// Prefer includes() for a boolean answer:
fruits.includes("plum");    // true

// Gotchas:
// - Uses strict equality (===): [1, 2].indexOf("1") -> -1
// - NaN is never found: [NaN].indexOf(NaN) -> -1
//   (includes() uses SameValueZero: [NaN].includes(NaN) -> true)
// - Index 0 is falsy: if (arr.indexOf(x)) misses a match at 0
// - Negative fromIndex counts from the end: fruits.indexOf("pear", -1) -> 3
// - lastIndexOf() searches backwards from the end
// - Sparse array holes are skipped
// - For objects, matches by reference only

// General form
// const result = array.method(...args);
// Mutator methods change the array in place AND hand back a value
// that is not always the array itself. Check each method's return.

// Example 1: shift removes from the front
const queue = ['a', 'b', 'c'];
const first = queue.shift();
// first is the removed element; queue is now changed

// Example 2: unshift adds to the front
const stack = ['x'];
const r = stack.unshift('y', 'z');
// check what r holds by reading the docs for unshift

// Common variations (each mutates the original array):
// pop()      -> returns the removed last element (undefined if empty)
// shift()    -> returns the removed first element (undefined if empty)
// splice()   -> returns an array of removed elements
// sort()     -> returns the same array reference, sorted
// reverse()  -> returns the same array reference, reversed
// fill()     -> returns the same array reference

// Gotchas:
// - Return values differ per method: a length, an element,
//   an array of removed items, or the array itself.
// - Non-mutating alternatives return NEW arrays:
//   concat, slice, map, filter, toSorted, toReversed, with.
// - Chaining only works on methods that return the array.
// - A method that returns a number cannot be chained like an array.

// General form
// arr.pop() -> removes the LAST element and returns that element
// (mutates arr; length decreases by 1)

const colors = ['red', 'green', 'blue'];
const last = colors.pop();
console.log(last);   // 'blue'
console.log(colors); // ['red', 'green']

const empty = [];
console.log(empty.pop()); // undefined (nothing to remove)

// Variations and gotchas:
// - Returns the removed element, NOT the new array or new length.
// - Contrast: push(x) returns the NEW LENGTH, not the array.
//     const n = [7].push(8); // n === 2
// - shift() removes/returns the FIRST element; unshift() adds to the front
//   and returns the new length.
// - pop() mutates in place, even on a const binding (const only
//   prevents reassignment).
// - Non-mutating alternative for the last item: arr.at(-1) or arr.slice(-1)
//   (slice returns an array, e.g. [9]).
// - Sparse/holey arrays: pop() on a trailing hole returns undefined.

// General form
// arr.shift() -> removes the FIRST element and returns it (mutates arr)
// Returns undefined if the array is empty

const colors = ['red', 'green', 'blue'];
const first = colors.shift();
// first  -> 'red'           (the removed element itself, not an array)
// colors -> ['green', 'blue'] (array is modified in place, length decreases by 1)

const empty = [];
empty.shift(); // -> undefined

// Related methods:
// arr.pop()          -> removes and returns the LAST element
// arr.unshift(a, b)  -> adds to the front, returns the NEW LENGTH
// arr.push(a, b)     -> adds to the end, returns the NEW LENGTH
// arr.splice(0, 1)   -> removes from the front but returns an ARRAY: ['red']

// Gotchas:
// - shift() mutates the original array; use arr.slice(1) or
//   const [head, ...rest] = arr; for a non-mutating alternative.
// - shift() re-indexes every remaining element, so it is O(n) on large arrays.
// - On sparse arrays a hole at index 0 is returned as undefined.

// General form
// array.methodName(...args)  // some methods mutate the array in place
// Every method has two outputs to keep apart:
//   1) the side effect on the array
//   2) the value the call evaluates to (its return value)

// Example: shift removes from the front
const letters = ['a', 'b', 'c'];
const first = letters.shift();
// letters is now ['b', 'c']; first holds what shift returned

// Example: push adds to the end
const nums = [10, 20];
const r = nums.push(30, 40);
// nums is now [10, 20, 30, 40]; r holds what push returned

// Gotchas
// - Mutators change the original array; they do not copy it.
// - Return values differ by method: pop/shift return the removed
//   element, push/unshift return a number, sort/reverse return the
//   same array reference.
// - Multiple arguments are inserted together, keeping their order:
//   arr.unshift(x, y) puts x, y at the start in that order.
// - To get a new array without mutating, use spread or toSpliced:
//   const copy = [z, ...arr];
// - Check the docs' "Return value" section instead of guessing.

// General form
// array.slice(start?, end?)
//   start: index to begin copying (inclusive); default 0
//   end:   index to stop before (exclusive); default array.length
//   returns: a NEW array holding a shallow copy of the selected range

const letters = ['a', 'b', 'c', 'd', 'e'];

const mid = letters.slice(1, 3);   // elements at index 1 and 2
const tail = letters.slice(-2);    // negative index counts from the end

// Variations and gotchas
// - slice() with no arguments makes a shallow copy of the whole array.
// - If start >= length, the result is an empty array [].
// - Negative values are offsets from the end: length + value.
// - end is exclusive: slice(1, 3) does not include index 3.
// - Shallow copy: nested objects/arrays are shared by reference.
// - Compare with splice(start, deleteCount, ...items), which is a
//   different method that changes the array it is called on.
// - Works on strings too (String.prototype.slice) and returns a string.
// - Return value and original array are separate objects; check each
//   one separately when reasoning about what a call produces.

// General form: mutates the array in place, returns an ARRAY of removed elements
// arr.splice(start, deleteCount?, item1?, item2?, ...)

const letters = ['a', 'b', 'c', 'd'];
const taken = letters.splice(2, 1);
// taken   -> ['c']            (always an array, even for one element)
// letters -> ['a', 'b', 'd']  (original array is modified)

// Insert without removing (deleteCount = 0)
const nums = [10, 20, 40];
nums.splice(2, 0, 30);   // returns []
// nums -> [10, 20, 30, 40]

// Replace elements
const colors = ['red', 'green', 'blue'];
colors.splice(1, 1, 'yellow'); // returns ['green']
// colors -> ['red', 'yellow', 'blue']

// Variations & gotchas:
// - Omit deleteCount: removes everything from start to the end
//     [1,2,3,4].splice(1) -> returns [2,3,4], array becomes [1]
// - Negative start counts from the end: arr.splice(-1, 1) removes the last item
// - To get a single removed value: const [x] = arr.splice(i, 1);
// - slice(start, end) does NOT mutate; splice does
// - toSpliced() (ES2023) returns a new array and leaves the original unchanged

// General form
// const result = arr.concat(value1, value2, /* ... */ valueN);
// Returns a NEW array: arr's elements followed by each argument.
// The original array is not modified.

const colors = ['red', 'green'];
const more = colors.concat(['blue'], 'pink');
// more   -> ['red', 'green', 'blue', 'pink']
// colors -> ['red', 'green']  (unchanged)
// more === colors -> false

const nums = [10];
const merged = nums.concat([20, 30], [[40]]);
// merged -> [10, 20, 30, [40]]  (only one level is flattened)

// Variations & gotchas:
// - Array arguments are spread one level; nested arrays stay nested.
// - Non-array arguments are appended as-is.
// - arr.concat() with no args makes a shallow copy.
// - Shallow: object elements are shared, not cloned.
//     const a = [{ n: 1 }]; const b = a.concat();
//     b[0].n = 9; // a[0].n is now 9 too
// - Compare with push(), which MUTATES the array and returns the new length:
//     const list = ['x']; list.push('y'); // returns 2, list -> ['x', 'y']
// - Spread syntax is a common alternative: [...colors, 'blue']
// - Sparse slots (holes) are preserved.

