const inner = { n: 1 };
const copy = [...[inner]];
copy[0].n = 9;  // inner.n is 9

// General form:
// const [name = defaultExpr] = iterable;
// The default is used only when the matched value is
// strictly the value undefined (or the element is missing).

const [x = 10] = [5];        // existing value is used
const [y = 10] = [];         // missing element -> default applies

// Object destructuring follows the same rule:
const { p = 'dflt' } = { p: 'given' };

// Variations and gotchas:
// - The default is evaluated lazily, only when needed:
//   const [m = compute()] = [3];   // compute() is not called
// - Defaults can use earlier bindings:
//   const [s = 1, t = s + 1] = [];
// - Other falsy values (0, '', false, NaN) are real values,
//   so they are kept rather than replaced.
// - Compare with ?? and ||, which treat values differently:
//   value ?? fallback   // nullish check
//   value || fallback   // falsy check
// - Defaults also work in function parameters:
//   function f({ k = 2 } = {}) {}
// - Check precisely which values trigger the default:
//   only one specific value does, not every 'empty-looking' one.

// General form: const [x, y, ...rest] = iterable;
// Each position binds the element at the same index.

const [first, second] = ['red', 'green', 'blue'];
// first === 'red', second === 'green'

// Skip elements with empty slots (elisions)
const [, , third] = [10, 20, 30, 40];
// third === 30

const [p, , r] = ['x', 'y', 'z'];
// p === 'x', r === 'z'  ('y' is skipped)

// Rest element collects the remainder (must be last)
const [head, ...tail] = [5, 6, 7];
// head === 5, tail is [6, 7]

// Defaults apply only when the value is undefined
const [m = 1, n = 2] = [undefined, null];
// m === 1, n === null

// Swap without a temp variable
let u = 1, v = 2;
[u, v] = [v, u];

// Gotchas:
// - Missing elements become undefined (no error).
// - Destructuring null/undefined or a non-iterable throws a TypeError.
// - A trailing comma after a rest element is a SyntaxError.
// - Works on any iterable: strings, Sets, Maps, generators.

// General form: pull values out of an iterable by position
const [a, b, ...others] = iterable;
// The rest element collects all REMAINING items into a NEW array

const [first, ...remaining] = ['x', 'y', 'z', 'w'];
// first     -> 'x'
// remaining -> ['y', 'z', 'w']   (always an array)

const [only, ...none] = [42];
// only -> 42, none -> []   (empty array, never undefined)

// Skip positions with holes
const [, second, ...after] = [10, 20, 30, 40];
// second -> 20, after -> [30, 40]

// Defaults apply when the value is undefined
const [p = 5, q = 7] = [1];
// p -> 1, q -> 7

// Works on any iterable (strings, Sets, Maps...)
const [ch, ...chars] = 'hey';
// ch -> 'h', chars -> ['e', 'y']

// Gotchas:
// - The rest element must be LAST: [...xs, last] is a SyntaxError
// - No trailing comma after a rest element: [a, ...r,] is a SyntaxError
// - Missing positions become undefined: const [m, n] = [1]; // n -> undefined
// - Object form also exists: const { k, ...restObj } = { k: 1, j: 2 };

// General form: object destructuring with renaming
// const { sourceKey: newName } = object;
// The left side of ':' is the property to read; the right side is the binding created.

const user = { id: 42, name: "Ada" };
const { id: userId, name } = user;
console.log(userId); // 42
console.log(name);   // "Ada"
// console.log(id);  // ReferenceError: id is not defined (only userId was bound)

// Rename + default value
const { role: userRole = "guest" } = user;
console.log(userRole); // "guest"

// Nested: the key before ':' is a pattern path, not a binding
const cfg = { db: { port: 5432 } };
const { db: { port: dbPort } } = cfg;
console.log(dbPort); // 5432 (no 'db' binding is created)

// Gotchas:
// - Renaming syntax looks like an object literal but reads in reverse:
//   { key: target } assigns obj.key to target.
// - Assigning to existing vars needs parentheses:
//   let x; ({ id: x } = user);
// - Shorthand { name } is the same as { name: name }.
// - Missing property gives undefined unless a default is supplied.
// - Destructuring null/undefined throws a TypeError.

// General form: object destructuring with default values
const { prop = defaultValue } = sourceObject;
const { prop: alias = defaultValue } = sourceObject;

// Example 1: missing property uses the default
const { color = 'red' } = { size: 3 };
// color === 'red'

// Example 2: present property keeps its value
const { count = 10 } = { count: 0 };
// count === 0  (0 is not undefined, so no default)

// Gotchas:
// - Defaults apply ONLY when the value is strictly undefined
//   (property missing, or explicitly set to undefined).
const { x = 5 } = { x: undefined }; // x === 5
const { y = 5 } = { y: null };      // y === null (null is a real value)
const { z = 5 } = { z: '' };        // z === '' (falsy but not undefined)
// - This differs from ||, which replaces any falsy value,
//   and ?? which replaces both null and undefined:
const w = null ?? 5;                // w === 5
// - Default expressions are evaluated lazily, only when needed.
// - Rename + default: const { id: userId = -1 } = obj;
// - Nested: const { opts: { depth = 1 } = {} } = obj;
// - Function params: function f({ limit = 20 } = {}) {}

// General form
// const { prop } = object;
// const { prop: newName } = object;
// const { prop = fallback } = object;
// const { prop: newName = fallback } = object;

// Example 1: reading and renaming
const user = { name: 'Ada', age: 36 };
const { name, age: years } = user;
// name -> 'Ada', years -> 36

// Example 2: default values
const { city = 'Unknown', name: n = 'Anon' } = { name: 'Bo' };
// A default is used only when the property value is undefined

// Variations and gotchas
// - Nested: const { p: { q } } = obj;  (throws if obj.p is null/undefined)
// - Rest: const { x, ...others } = obj;  collects remaining own enumerable props
// - Destructuring null or undefined throws a TypeError
// - Defaults do NOT apply to null, 0, '' or false
// - Without const/let, wrap in parentheses: ({ x } = obj);
// - In parameters: function f({ a = 1, b } = {}) { }
// - Properties are looked up by name, not by position (unlike arrays)

// General form
const { prop, other: alias = defaultVal } = sourceObject;
const [first, , third = 0, ...rest] = iterable;

// Examples
const user = { name: 'Ada', age: 36 };
const { name, role = 'guest' } = user; // name='Ada', role='guest'
const [x, y] = [10, 20];               // x=10, y=20

// Gotchas & variations
// Object destructuring needs a value that can be converted to an object:
// const { length } = 'hi';   // OK: primitives are boxed -> 2
// const { foo } = undefined; // TypeError: cannot destructure undefined
// const { foo } = null;      // TypeError: cannot destructure null
// Guard with a fallback:
const { size } = maybeObj ?? {};
// Defaults apply only when the value is undefined, not null:
const { v = 5 } = { v: null }; // v === null
// In parameters, default the whole pattern:
function f({ id } = {}) { return id; } // f() -> undefined
// Assigning to existing variables needs parentheses:
let p; ({ p } = { p: 1 });

// General form: if a variable's name matches the key you want,
// you can write the identifier alone inside { }.
// { id }            is the same as   { id: id }
// { id, label }     is the same as   { id: id, label: label }

const city = "Lima";
const zip = 15001;
const place = { city, zip };
// place -> { city: "Lima", zip: 15001 }

// Mixed with regular key: value pairs
const count = 3;
const stats = { count, max: 10 };
// stats -> { count: 3, max: 10 }

// Method shorthand (a related form)
const greeter = {
  greet() { return "hi"; } // same as greet: function () { ... }
};

// Gotchas:
// - The variable must exist in scope: { missing } throws ReferenceError.
// - Only a plain identifier works: { a.b } and { "x-y" } are syntax errors.
// - The value is copied when the object is created. Changing the variable
//   later does not update the property.
// - Do not confuse this with destructuring: const { city } = place;
//   reads a property into a variable. This form does the reverse.
// - Computed keys use brackets instead: { [key]: value }

// General form: { [expression]: value }
// The expression in brackets is evaluated, converted to a property key
// (string or symbol), and used as the property name.

const field = "name";
const user = { [field]: "Ada" };
// user => { name: "Ada" }

const prefix = "item";
const list = { [prefix + "_" + 2]: true, [`${prefix}Count`]: 5 };
// list => { item_2: true, itemCount: 5 }

// Variations:
const tag = Symbol("tag");
const o1 = { [tag]: "x" };           // symbol keys are kept as symbols
const o2 = { [1 + 1]: "two" };        // number key -> string "2"
const o3 = { ["say" + "Hi"]() { return "hi"; } }; // computed method name
const o4 = { get ["v" + 1]() { return 1; } };     // computed getter

// Gotchas:
// { field: 1 }   -> key is literally "field" (no brackets = no evaluation)
// { [field]: 1 } -> key is the VALUE of field
// Objects as keys are stringified: { [{}]: 1 } -> { "[object Object]": 1 }
// Expressions are evaluated left to right, once, when the literal runs.
// Duplicate computed keys: the later one wins.

// General form
for (const item of iterable) {
  // item is each VALUE produced by the iterable's iterator
}

// Example: arrays give elements
for (const n of [10, 20, 30]) {
  console.log(n); // 10, 20, 30
}

// Example: strings give characters (code points)
for (const ch of "hi") {
  console.log(ch); // "h", "i"
}

// Variations
for (const [k, v] of new Map([["x", 1]])) {} // Map yields [key, value] pairs
for (const s of new Set([1, 2])) {}          // Set yields values
for (const [i, el] of ["p", "q"].entries()) {} // need index? use .entries()
for (let x of arr) { x = 0; }                 // reassigning x does not change arr

// Gotchas
// for...in iterates enumerable property KEYS (strings: "0", "1"...), not values
// Plain objects are not iterable: for (const v of {a: 1}) throws TypeError
//   use Object.values(obj), Object.keys(obj), or Object.entries(obj)
// break, continue, and return work; break calls the iterator's return()
// Works with any iterable: arguments, NodeList, generators, typed arrays
// for await (const v of asyncIterable) {} inside async functions

