// General form
// JSON.stringify(value, replacer?, space?)
// Returns a JSON string (or undefined for some top-level inputs).

// Example 1: how different property values are handled
const s1 = JSON.stringify({ n: 5, f() {}, t: true, nul: null });
// Each value type has its own rule in objects.

// Example 2: arrays vs. objects
const s2 = JSON.stringify([function () {}, Symbol('x')]);
// Array slots must keep their positions, so they are treated differently
// from object properties.

// Gotchas / variations
// - Values with no JSON representation (undefined, functions, symbols)
//   are handled differently depending on whether they appear in an
//   object property, an array element, or at the top level.
// - null is a valid JSON value and is kept.
// - NaN, Infinity and -Infinity become null.
// - Symbol-keyed properties are ignored.
// - Only own enumerable string-keyed properties are included.
// - Date uses toJSON; any object with toJSON() is serialized from its result.
// - BigInt throws a TypeError unless you provide toJSON or a replacer.
// - Circular references throw a TypeError.
// - replacer (function or array of keys) can filter or transform values.
// - space (number or string) pretty-prints the output.

// General form
// JSON.stringify(value, replacer?, space?)  -> string (or undefined)

// JSON has no representation for some JS values, so stringify
// handles them differently depending on WHERE they appear.

// 1) As object property values: the property is omitted
JSON.stringify({ a: 1, b: function () {}, c: Symbol('s') });
// -> '{"a":1}'

// 2) As array elements: the slot must stay, so a placeholder is written
JSON.stringify([function () {}, Symbol('s')]);
// -> '[null,null]'

// 3) As the top-level value: the result is the value undefined (not a string)
JSON.stringify(function () {});
// -> undefined

// Gotchas (comments only):
// - Values skipped in objects / replaced in arrays: undefined, functions, symbols.
// - NaN, Infinity, -Infinity become null everywhere.
// - Sparse array holes are visited as undefined, so follow the array rule.
// - Date uses toJSON() and becomes an ISO string.
// - BigInt throws a TypeError.
// - A replacer function or toJSON() can change what gets serialized.

// General form
// JSON.stringify(value, replacer?, space?)
// Returns a JSON string (or undefined for some top-level inputs).

// Example 1: which values survive inside an object
const o = { n: 5, s: "hi", t: true, nul: null, d: new Date(0) };
JSON.stringify(o);
// numbers, strings, booleans, null are kept; Date uses toJSON() -> ISO string

// Example 2: arrays vs objects
JSON.stringify([1, undefined, Symbol("x")]);
// In ARRAYS, unsupported values are converted to null (keeps positions)

// Example 3: replacer and indentation
JSON.stringify({ x: 1, y: 2 }, ["x"]);        // array replacer = allowed keys
JSON.stringify({ x: 1 }, null, 2);             // pretty print with 2 spaces
JSON.stringify({ x: 1, y: 2 }, (k, v) => typeof v === "number" ? v * 2 : v);

// Gotchas (comments)
// - Object properties whose values are undefined, functions, or symbols are
//   handled specially: they are not written as normal values.
// - Top-level undefined/function/symbol input returns undefined (not a string).
// - NaN and Infinity become null.
// - If an object has toJSON(), its return value is serialized instead.
// - Circular references throw TypeError; BigInt throws TypeError.
// - Only own enumerable string-keyed properties are included.
// - Map/Set serialize as {} unless converted first.

// General form
JSON.parse(text)            // -> JS value described by the JSON text
JSON.parse(text, reviver)   // reviver(key, value) can transform each value

// Examples
const user = JSON.parse('{"name":"Ada","tags":["x","y"]}');
user.name;        // "Ada"
user.tags[1];     // "y"

JSON.parse('[1, 2, 3]');  // [1, 2, 3]
JSON.parse('42');         // 42 (top-level primitives are allowed)
JSON.parse('"hi"');       // "hi"
JSON.parse('null');       // null

// Reviver: convert date strings back to Date objects
const obj = JSON.parse('{"when":"2024-05-01T00:00:00Z"}', (k, v) =>
  k === 'when' ? new Date(v) : v);

// Gotchas
// - Invalid JSON throws SyntaxError: wrap in try/catch for untrusted input
// - Keys must use double quotes: JSON.parse("{'k':1}") throws
// - No trailing commas, comments, undefined, NaN, or functions
// - Dates come back as strings, not Date objects (use a reviver)
// - Very large integers lose precision (parsed as Number)
// - Opposite direction: JSON.stringify(value)

// General form: function declaration
function name(param1, param2) {
  return param1 + param2;
}

// Declarations are hoisted with their body: callable before the line they appear on
console.log(greet('Ada')); // 'Hi, Ada'
function greet(who) {
  return 'Hi, ' + who;
}

// Function expressions are NOT hoisted the same way
// sum(2, 3);            // TypeError: sum is not a function (var is hoisted as undefined)
var sum = function (a, b) { return a + b; };

// const/let expressions and arrow functions: temporal dead zone
// square(4);            // ReferenceError: Cannot access 'square' before initialization
const square = (n) => n * n;

// Gotchas:
// - Hoisting is per scope: a declaration inside a function is hoisted to the top of that function
// - Declarations in blocks ({ ... }) are block-scoped in strict mode; sloppy mode behavior varies
// - Class declarations are hoisted but stay in the TDZ (cannot be used before definition)
// - A later declaration with the same name overwrites an earlier one

expression();  // ReferenceError
const expression = function () {
  return 1;
};

function f(a = 1) {
  return a;
}
f(undefined)  // 1
f(null)       // null

questions.code:
function f(a, b = a) {
  return b;
}

query.syntax:
// General form
// function name(p1, p2 = expression, p3 = expression) { ... }
//
// A default is evaluated at call time, only when the argument is
// undefined (missing or explicitly undefined). Not for null, 0, '' or false.
// Parameters are initialized left to right, each in its own scope
// step, like let bindings.

function area(w, h = w * 2) {
  return w * h;
}

function tag(name, label = name.toUpperCase(), note = label + '!') {
  return note;
}

// Variations and gotchas:
// - Defaults can call functions: function g(x = makeId()) {}
//   makeId runs on every call that needs it, not once.
// - Defaults can use outer variables and earlier parameters.
// - Temporal dead zone applies to parameters: a default that reads
//   a parameter declared later (or itself) throws a ReferenceError.
//     function bad(a = b, b = 1) {}
// - Parameters with defaults do not count toward function.length
//   after the first default.
// - Destructuring can have defaults too: function h({ x = 1 } = {}) {}
// - With defaults present, the parameter list has its own scope,
//   separate from the function body's var declarations.

switch (1) {
  case "1":
    break;  // does not match
  case 1:
    break;  // matches
}

// General form
switch (expression) {
  case valueA:
    // statements
    break;
  case valueB:
    // statements
    break;
  default:
    // statements when no case matches
}

// Example 1: matching uses strict equality (===)
let color = "red";
switch (color) {
  case "red":
    console.log("stop");
    break;
  case "green":
    console.log("go");
    break;
  default:
    console.log("unknown");
}

// Example 2: several labels sharing one block
let day = 6;
switch (day) {
  case 6:
  case 7:
    console.log("weekend");
    break;
  default:
    console.log("weekday");
}

// Notes and gotchas
// - Execution starts at the first matching case, then continues
//   statement by statement until a break, return, throw, or the end
//   of the switch block. Labels themselves do not stop execution.
// - An empty case with no statements simply continues into the next one.
// - default can appear anywhere; it runs only if no case matches,
//   but if it is not last, flow still continues past it without break.
// - "5" and 5 do not match (strict equality).
// - All cases share one block scope; wrap a case in { } to use let/const safely.
// - Intentional continuing into the next case is best marked with a comment.

// General form: evaluate an expression, discard its result, yield undefined
void expression

// Examples
void 42;                 // undefined
void 'hello';            // undefined
let n = 1;
void (n += 5);           // undefined, but n is now 6 (side effect still runs)

// Common uses
// 1. A reliable undefined (older code, when `undefined` could be shadowed)
const nothing = void 0;  // same as undefined

// 2. Run an IIFE without a leading '(' (statement must not start with 'function')
void function init() { console.log('ready'); }();

// 3. Arrow fn that must not leak a return value
button.onclick = () => void doWork();  // returns undefined, not doWork()'s result

// Gotchas
// - High precedence: void 2 + 3  -> NaN  (parsed as (void 2) + 3)
//   Use parentheses: void (2 + 3) -> undefined
// - The operand IS evaluated; only its value is thrown away.
// - typeof void 'x'  -> 'undefined'
// - 'javascript:void(0)' in hrefs is legacy; prefer event handlers.

// General form
//   delete object.property
//   delete object[expression]
// The result is a boolean, not the deleted value.

const cfg = { host: "x", port: 80 };
const r1 = delete cfg.port;     // removes the property from cfg
const r2 = delete cfg.missing;  // property does not exist

// Property attributes matter:
const locked = {};
Object.defineProperty(locked, "id", { value: 7, configurable: false });
// delete locked.id -> property stays
//   sloppy mode: evaluates to false
//   strict mode ("use strict", modules, classes): throws TypeError

// Gotchas
// - Only own properties are removed; inherited ones on the prototype are untouched.
// - Deleting a nonexistent property does not fail.
// - delete on a plain variable name is a SyntaxError in strict mode.
// - Variables declared with var/let/const are not configurable properties.
// - Array elements: delete arr[i] leaves a hole and does not change length.
// - Use Reflect.deleteProperty(obj, key) to get a boolean without throwing.
// - Object.freeze / Object.seal make all own properties non-configurable.

// General form
delete arr[index];   // removes the property, returns true

// Example: delete leaves a hole (sparse array)
const colors = ["red", "green", "blue", "cyan"];
delete colors[2];
console.log(colors);        // ["red", "green", <1 empty item>, "cyan"]
console.log(colors.length); // 4  (length unchanged)
console.log(colors[2]);     // undefined
console.log(2 in colors);   // false (the index no longer exists)

// To actually remove and shift elements, use splice
const nums = [10, 20, 30, 40];
nums.splice(1, 1);          // removes 1 item at index 1
console.log(nums);          // [10, 30, 40]
console.log(nums.length);   // 3

// Gotchas:
// - forEach/map/filter skip holes; for...of and spread yield undefined
// - arr[i] = undefined keeps the index (i in arr === true), unlike delete
// - Setting arr.length = n truncates the array
// - Other ways to remove items: pop(), shift(), filter() (new array), toSpliced()
// - delete on a non-configurable property returns false (TypeError in strict mode)

// General form
// key in object   -> true if key exists on the object OR anywhere on its prototype chain

const car = { make: "Volvo" };
"make" in car;            // true  (own property)
"hasOwnProperty" in car;  // true  (inherited from Object.prototype)
"model" in car;           // false

// Own-only check: use Object.hasOwn (or obj.hasOwnProperty)
Object.hasOwn(car, "make");            // true
Object.hasOwn(car, "hasOwnProperty");  // false (inherited, not own)

// Arrays: checks indexes/keys, not values
const list = ["a", "b"];
1 in list;        // true  (index 1 exists)
"a" in list;      // false (values are not keys)
"length" in list; // true

// Gotchas:
// - A property set to undefined still exists: "x" in { x: undefined } -> true
// - After delete, it is gone: delete car.make; "make" in car -> false
// - Objects with no prototype inherit nothing:
//   "toString" in Object.create(null) -> false
// - Right side must be an object: "a" in "abc" throws TypeError
// - Symbol keys work too: Symbol.iterator in [] -> true
// - Private fields: #field in obj (inside the class body)

// General form
Object.hasOwn(obj, key)   // true only if key is an OWN property of obj

// Examples
const car = { make: "Volvo" };
Object.hasOwn(car, "make");      // true  (own property)
Object.hasOwn(car, "valueOf");   // false (inherited from Object.prototype)
"valueOf" in car;                // true  (`in` walks the prototype chain)

const child = Object.create({ wheels: 4 });
Object.hasOwn(child, "wheels");  // false (lives on the prototype)
child.wheels;                    // 4     (still readable via lookup)

// Variations & gotchas
// - Works on null-prototype objects, unlike obj.hasOwnProperty():
const bare = Object.create(null);
bare.id = 7;
Object.hasOwn(bare, "id");       // true
// bare.hasOwnProperty("id");    // TypeError: not a function
// - Safer than obj.hasOwnProperty(k), which can be shadowed/overridden.
// - Non-enumerable own props still count: Object.hasOwn([], "length") // true
// - Value doesn't matter: { x: undefined } -> Object.hasOwn(o, "x") // true
// - Throws TypeError if obj is null or undefined.
// - Keys are coerced to property keys; Symbols are supported.

