const obj = {};
Object.defineProperty(obj, "hidden", { value: 1, enumerable: false });
const sym = Symbol("s");
obj[sym] = 2;
obj.visible = 3;
Object.keys(obj);

query.syntax:
// General form
// Math.max(...values)  -> largest of the numeric arguments
// Math.min(...values)  -> smallest of the numeric arguments
// Arguments are converted to numbers before comparing.

// Examples
Math.max(3, 9, 4);        // 9
Math.min(3, 9, 4);        // 3
Math.max(...[5, 12, 7]);  // 12 (spread an array into arguments)

// Variations and gotchas
// - Math.max/min do not accept an array directly: Math.max([1, 2]) converts the
//   array to a number (NaN for multi-element arrays).
// - If any argument converts to NaN, the result is NaN.
// - Non-numbers are coerced: Math.max('8', 2) uses 8; null becomes 0; undefined becomes NaN.
// - Think of each function as folding over its arguments, starting from an
//   identity value that any real number would beat. Consider what that
//   starting value must be for each function when nothing is passed.
// - Very large arrays spread as arguments can exceed engine argument limits;
//   use reduce for huge inputs:
//   arr.reduce((a, b) => Math.max(a, b), -Infinity)
// - Math.max(-0, 0) is 0 (+0 is treated as larger than -0).

choices.code:
function sortNumbers(values) {
  return [...values].sort((a, b) => a - b);
}

query.syntax:
// General form
// arr.sort()                  // sorts IN PLACE, returns the same array
// arr.sort((a, b) => result)  // result < 0: a first; > 0: b first; 0: keep order

// Numeric ascending / descending
const scores = [42, 7, 100, 15];
const asc = [...scores].sort((x, y) => x - y);   // [7, 15, 42, 100]
const desc = [...scores].sort((x, y) => y - x);  // [100, 42, 15, 7]

// Sort objects by a numeric property
const items = [{ n: 3 }, { n: 1 }, { n: 2 }];
items.sort((p, q) => p.n - q.n);

// Gotchas:
// - With no comparator, elements are converted to strings and compared
//   by UTF-16 code units: [25, 3, 100].sort() -> [100, 25, 3]
// - sort() mutates the original array; copy first with [...arr] or arr.slice()
// - ES2023: arr.toSorted(compareFn) returns a new sorted array without mutating
// - undefined elements are always moved to the end; comparator isn't called on them
// - Strings: use (a, b) => a.localeCompare(b) for locale-aware ordering
// - Sort is stable (ES2019+): equal elements keep their relative order

// General form
// a === b   strict: true only if same type AND same value (no conversion)
// a == b    loose: converts operands to a common type, then compares
// a !== b / a != b  are the negated forms

// Examples
const count = 1;
count === 1;      // true
count === '1';    // false (number vs string)
count == '1';     // true  ('1' converted to 1)

false == 0;       // true  (false -> 0)
false === 0;      // false
null == undefined;  // true
null === undefined; // false
' \t' == 0;       // true  (whitespace string -> 0)
[1] == 1;         // true  ([1] -> '1' -> 1)

// Gotchas
// NaN is never equal to anything, even itself:
//   NaN === NaN  // false -> use Number.isNaN(x)
// +0 === -0 is true -> use Object.is(+0, -0) to tell them apart (false)
// Objects compare by reference, not contents:
//   ({}) === ({})  // false
// Prefer === / !== unless you deliberately want conversion;
// x == null is a common idiom matching both null and undefined.

